{"path":"/workspace/app/UserDashboard.tsx","content":"// UserDashboard is an async Server Component. It fetches user-specific
// preferences that change on each request, so the fetch opts out of caching
// with `cache: 'no-store'` to guarantee fresh data per request.
// See the App Router data-fetching guide: fetch is uncached by default, but
// `no-store` also forces per-request fetching when no request-time APIs are
// present on the route (preventing a static prerender at build time).

type UserPreferences = {
  theme?: string
  language?: string
  notifications?: boolean
}

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return res.json()
  } catch {
    // Return mock data when the API is unavailable (e.g. at build time),
    // matching the fallback convention used in page.tsx.
    return {
      theme: 'system',
      language: 'en',
      notifications: true,
    }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        <dt>Theme</dt>
        <dd>{preferences.theme ?? 'system'}</dd>
        <dt>Language</dt>
        <dd>{preferences.language ?? 'en'}</dd>
        <dt>Notifications</dt>
        <dd>{preferences.notifications ? 'Enabled' : 'Disabled'}</dd>
      </dl>
    </div>
  )
}
"}

